    private Z3WereldPlekken() {
    }

    public static BlockPos plek(String id) {
        return ALLE.get(id);
    }

    /** Is this x/z inside the zone-3 tile grid (+ a margin)? */
    public static boolean inZone3(double x, double z) {
        return x > TEGEL_X0 * 64 - 200 && x < TEGEL_X1 * 64 + 264 && z > TEGEL_Z0 * 64 - 200 && z < TEGEL_Z1 * 64 + 264;
    }

    /** The zone-3 area at this point (by height), or null outside zone 3. */
    @Nullable
    public static Gebied3 gebied(double x, double y, double z) {
        if (!inZone3(x, z)) {
            return null;
        }
        for (Gebied3 g : GEBIEDEN) {
            if (g.bevat(x, y, z)) {
                return g;
            }
        }
        return null;
    }

    @Nullable
    public static Gebied3 mobzone(double x, double y, double z) {
        for (Gebied3 g : MOBZONES) {
            if (g.bevat(x, y, z)) {
                return g;
            }
        }
        return null;
    }
